{
  "observed_sentiment": "overheated",
  "claims": [
    {
      "claim_text": "주가가 신고가 부근에 도달하여 과열 구간으로 판단되며, 차익실현 매도세가 강하게 작용하고 있다.",
      "claim_stance": "bearish",
